  box-shadow:none !important; overflow:hidden !important;
  object-fit:cover !important; background-size:cover !important; background-position:center !important;
}
.msg-avatar-me-container:has(img, .msg-avatar-me-inner)::after,
.msg-avatar-them-container:has(img, .msg-avatar-them-inner)::after{
  position:absolute; left:50%; top:calc(100% + 2px); transform:translateX(-50%);
  font-size:10px; font-weight:700; color:var(--ry-search-ink);
  white-space:nowrap; letter-spacing:.02em; line-height:1.2;
  pointer-events:none; z-index:2;
}
.msg-avatar-me-container:has(img, .msg-avatar-me-inner)::after{ content:var(--ry-tag-me) !important; }
.msg-avatar-them-container:has(img, .msg-avatar-them-inner)::after{ content:var(--ry-tag-ta) !important; }

/* ==========================================================
   3. 引用  气泡上方:左侧圆形小头像 + 名字内容同行 + 右侧细线灰色转发图标
   ========================================================== */
.msg-reply-block{ display:none !important; }
.msg-reply-block-detached{
  display:flex !important; order:-1 !important;
  position:relative !important; box-sizing:border-box !important;
  flex-flow:row nowrap !important; align-items:center !important; gap:4px !important;
  width:fit-content !important; min-width:0 !important; max-width:66vw !important;
  margin:0 0 5px 0 !important; padding:0 !important;
  background:transparent !important; border:0 !important; border-left:0 !important;
  border-radius:0 !important; box-shadow:none !important;
  backdrop-filter:none !important; -webkit-backdrop-filter:none !important;
  transform:none !important; clip-path:none !important; opacity:1 !important;
  line-height:1.3 !important; white-space:nowrap !important; overflow:visible !important;
}
.msg-reply-detached-me{ align-self:flex-end !important; margin-left:auto !important; }
.msg-reply-detached-them{ align-self:flex-start !important; margin-right:auto !important; }
.msg-reply-block-detached::before{
  content:"" !important; flex:0 0 16px; width:16px; height:16px;
  border-radius:50%; background-color:var(--ry-card-ic);
  background-size:cover; background-position:center; background-repeat:no-repeat;
  margin-right:2px; pointer-events:none;
}
.msg-reply-detached-me::before{ background-image:var(--char-avatar) !important; }
.msg-reply-detached-them::before{ background-image:var(--user-avatar) !important; }
.msg-reply-block-detached::after{
  content:"" !important; flex:0 0 17px; width:17px; height:17px; margin-left:3px;
  background:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke-linecap='round' stroke-linejoin='round'><path d='M12 3.2a8.8 8.8 0 1 0 8.5 11' stroke='%23c4c4c4' stroke-width='1.3'/><path d='M12 7.8a4.2 4.2 0 1 0 4.2 4.2' stroke='%239a9a9a' stroke-width='1.4'/><path d='M12.6 11.4L18.2 5.8' stroke='%239a9a9a' stroke-width='1.4'/><path d='M15.4 5.4H18.6V8.6' stroke='%239a9a9a' stroke-width='1.4'/></svg>") no-repeat center / contain !important;
  pointer-events:none;
}
.msg-reply-block-detached > *{
  display:inline !important; flex:0 1 auto !important; min-width:0 !important;
  color:var(--ry-search-ink) !important;
  font-size:11px !important; font-weight:700 !important; font-style:normal !important;
  background:transparent !important; margin:0 2px 0 0 !important; line-height:1.3 !important;
  white-space:nowrap !important;
}
.msg-reply-detached-text,
.msg-reply-detached-media{
  max-width:44vw !important; overflow:hidden !important; text-overflow:ellipsis !important;
}
.msg-reply-detached-name::after{ content:"" !important; }

/* ==========================================================
   4. 翻译(WeChat 修复版)  点气泡展开/收起
   ========================================================== */
.msg-translation-wrapper{
  position:static !important; height:0 !important; min-height:0 !important;
  margin:0 !important; padding:0 !important; line-height:0 !important;
  background:transparent !important; border:0 !important; overflow:visible !important;
}
.msg-translation-wrapper .msg-translation-content{ display:none !important; }

.msg-translation-btn{
  position:absolute !important; inset:0 !important;
  top:0 !important; left:0 !important; right:0 !important; bottom:0 !important;
  width:100% !important; height:100% !important; transform:none !important;
  display:block !important; margin:0 !important; padding:0 !important;
  background:transparent !important; border:0 !important; box-shadow:none !important;
  border-radius:inherit !important; outline:none !important;
  font-size:0 !important; line-height:0 !important; color:transparent !important; opacity:1 !important;
  overflow:hidden !important; z-index:8 !important; cursor:pointer !important;
  -webkit-tap-highlight-color:transparent !important;
}
.msg-translation-btn > *{ opacity:0 !important; }
.msg-translation-btn::before,
.msg-translation-btn::after{ content:none !important; }

.msg-translation-detached{
  display:block !important; box-sizing:border-box !important;
  width:fit-content !important; min-width:0 !important; max-width:68vw !important;
  margin:4px 0 0 0 !important;
}
.msg-translation-detached-them{ align-self:flex-start !important; }
.msg-translation-detached-me{ align-self:flex-end !important; }
.msg-translation-detached-content{
  position:relative !important; box-sizing:border-box !important;
  display:block !important; width:max-content !important; max-width:68vw !important; min-width:0 !important;
  padding:9px 12px 8px !important; margin:0 !important;
  background:var(--ry-tr-bg) !important; border:1px solid var(--ry-tr-line) !important;
  border-radius:4px !important; box-shadow:none !important; text-shadow:none !important;
  color:var(--ry-tr-ink) !important; font-size:16px !important; font-weight:400 !important;
  line-height:22px !important; white-space:normal !important; word-break:break-word !important;
}
.msg-translation-detached-content *{ color:var(--ry-tr-ink) !important; font-weight:400 !important; }
.msg-translation-detached-content::before{ content:none !important; }
.msg-translation-detached-content::after{
  content:"由WeChat提供翻译支持" !important;
  position:static !important; display:block !important;
  margin:4px 0 0 !important; padding-left:18px !important;
  min-height:14px !important; font-size:12px !important; line-height:14px !important;
  color:var(--ry-tr-gray) !important; white-space:nowrap !important;
  background:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><circle cx='12' cy='12' r='11' fill='%23B5B5B5'/><polyline points='7 12.5 10.5 16 17 9' fill='none' stroke='%23ffffff' stroke-width='2.4' stroke-linecap='round' stroke-linejoin='round'/></svg>") no-repeat left center / 13px 13px !important;
}
.msg-translation-detached-content del,
.msg-translation-detached-content s{ text-decoration:none !important; }

/* ==========================================================
   5. 思维链  排在最上面 · 小白胶囊:默认联系人头像 + 浅灰「ToT...」 + 小箭头
   ========================================================== */
.nuo-thinking-wrap{ order:-2 !important; }
.msg-content-stack > :has(> .nuo-thinking-btn),
.msg-content-stack > :has(.nuo-thinking-wrap){ order:-2 !important; }

.nuo-thinking-btn{
  position:relative !important;
  display:inline-flex !important; flex-direction:row !important;
  align-items:center !important; gap:6px !important;
  width:auto !important; height:24px !important; min-height:0 !important;
  padding:0 10px 0 3px !important; margin:0 0 5px 0 !important;
  background:var(--ry-card) !important; background-image:none !important;
  border:1px solid var(--ry-pill-line) !important; border-radius:9999px !important;
  box-shadow:none !important; box-sizing:border-box !important;
  backdrop-filter:none !important; -webkit-backdrop-filter:none !important;
  color:var(--ry-pill-ink) !important; overflow:visible !important;
}
.nuo-thinking-btn .nuo-thinking-arrow,
.nuo-thinking-btn .nuo-thinking-icon{ display:none !important; }
.nuo-thinking-btn::before{
  content:"" !important; position:static !important; inset:auto !important; opacity:1 !important;
  flex:0 0 18px; width:18px; height:18px; order:-1; border-radius:50%;
  background:var(--ry-pill-face-bg) !important;
}
.nuo-thinking-btn .nuo-thinking-label{
  position:relative !important;
  font-size:0 !important; line-height:0 !important; color:transparent !important;
  display:inline-flex !important; align-items:center !important;
}
.nuo-thinking-btn .nuo-thinking-label::before{
  content:"" !important; position:absolute; left:-24px; top:50%; transform:translateY(-50%);
  width:18px; height:18px; background-color:var(--ry-pill-face); pointer-events:none;
  -webkit-mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><circle cx='12' cy='9.2' r='4.2'/><path d='M4.2 21c0-4.3 3.5-6.7 7.8-6.7s7.8 2.4 7.8 6.7z'/></svg>") no-repeat center/72% 72%;
          mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><circle cx='12' cy='9.2' r='4.2'/><path d='M4.2 21c0-4.3 3.5-6.7 7.8-6.7s7.8 2.4 7.8 6.7z'/></svg>") no-repeat center/72% 72%;
}
.nuo-thinking-btn .nuo-thinking-label::after{
  content:"ToT..." !important;
  font-size:13px; font-weight:500; line-height:16px; letter-spacing:.4px;
  color:var(--ry-pill-ink);
}
.nuo-thinking-btn::after{
  content:"" !important; position:static !important; inset:auto !important; opacity:1 !important;
  flex:0 0 9px; width:9px; height:9px; order:99;
  background:var(--ry-chev) !important;
  -webkit-mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><path d='M4 8c2.5 0 5 4 8 7 3-3 5.5-7 8-7-1 4-5 9-8 11-3-2-7-7-8-11z'/></svg>") no-repeat center/contain;
          mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><path d='M4 8c2.5 0 5 4 8 7 3-3 5.5-7 8-7-1 4-5 9-8 11-3-2-7-7-8-11z'/></svg>") no-repeat center/contain;
  transition:transform .2s ease;
}
.nuo-thinking-btn.is-open::after{ transform:rotate(180deg); }

/* ==========================================================
   6. 图片  白色圆角外壳 + 一圈细线内框 · 原图 1:1 填满内框
            底部圆钮(::before,独立底色+细边) + 信封(::after)
   ========================================================== */
:is(.msg-image-card, .msg-image-wrapper){
  position:relative !important; box-sizing:border-box !important;
  width:var(--ry-img-w) !important; max-width:var(--ry-img-w) !important; min-width:0 !important;
  height:auto !important; aspect-ratio:auto !important;
  padding:9px 9px 30px !important; margin:0 0 24px 0 !important;
  background:var(--ry-shell) !important; background-image:none !important;
  border:1px solid var(--ry-shell-line) !important; border-radius:18px !important;
  box-shadow:0 1px 6px rgba(0,0,0,.04) !important;
  overflow:visible !important;
}
:is(.msg-image-card, .msg-image-wrapper)::before{
  content:"" !important; position:absolute !important;
  left:50% !important; bottom:-22px !important; transform:translateX(-50%) !important;
  width:46px !important; height:46px !important; border-radius:50% !important;
  box-sizing:border-box !important;
  background:var(--ry-btn) !important;
  border:1px solid var(--ry-btn-line) !important;
  box-shadow:0 2px 8px rgba(0,0,0,.08) !important;
  pointer-events:none !important; z-index:3 !important;
}
:is(.msg-image-card, .msg-image-wrapper)::after{
  content:"" !important; position:absolute !important;
  left:50% !important; bottom:-9px !important; transform:translateX(-50%) !important;
  width:20px !important; height:20px !important; border-radius:0 !important;
  background:var(--ry-env) !important; box-shadow:none !important;
  -webkit-mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><path d='M3 6.5A1.5 1.5 0 0 1 4.5 5h15A1.5 1.5 0 0 1 21 6.5v.4l-9 5.6-9-5.6zM3 9.1l8.5 5.3a1 1 0 0 0 1 0L21 9.1v8.4A1.5 1.5 0 0 1 19.5 19h-15A1.5 1.5 0 0 1 3 17.5z'/></svg>") no-repeat center/contain !important;
          mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><path d='M3 6.5A1.5 1.5 0 0 1 4.5 5h15A1.5 1.5 0 0 1 21 6.5v.4l-9 5.6-9-5.6zM3 9.1l8.5 5.3a1 1 0 0 0 1 0L21 9.1v8.4A1.5 1.5 0 0 1 19.5 19h-15A1.5 1.5 0 0 1 3 17.5z'/></svg>") no-repeat center/contain !important;
  pointer-events:none !important; z-index:4 !important;
}
:is(.msg-image-card, .msg-image-wrapper) > :not(.live-photo-badge){
  position:relative !important; display:block !important; box-sizing:border-box !important;
  width:100% !important; height:auto !important; aspect-ratio:1 / 1 !important;
  max-width:none !important; max-height:none !important;
  margin:0 !important; padding:0 !important; transform:none !important;
  background:transparent !important;
  border:1px solid var(--ry-frame-line) !important; border-radius:14px !important;
  box-shadow:none !important; overflow:hidden !important; z-index:1 !important;
}
:is(.msg-image-card, .msg-image-wrapper) img{
  display:block !important; box-sizing:border-box !important;
  width:100% !important; height:100% !important;
  max-width:none !important; max-height:none !important;
  aspect-ratio:1 / 1 !important; object-fit:cover !important; object-position:center !important;
  padding:0 !important; border:0 !important; border-radius:13px !important;
  background:transparent !important; box-shadow:none !important; filter:none !important;
}
:is(.msg-image-card, .msg-image-wrapper) > img{
  border:1px solid var(--ry-frame-line) !important; border-radius:14px !important;
}
:is(.msg-image-card, .msg-image-wrapper) .live-photo-badge{ z-index:5 !important; }

/* ==========================================================
   7. 卡片  浅灰白底 · 灰框 8px · 灰字灰图标
   ========================================================== */
.msg-transfer-card,
.msg-videocall-card,
.msg-loc-card,
.msg-shopask-card,
.msg-file-card,
.msg-history-card,
.msg-delivery-card,
