  backdrop-filter:none !important; -webkit-backdrop-filter:none !important;
}
:is(.msg-transfer-card,.msg-videocall-card,.msg-loc-card,.msg-shopask-card,.msg-file-card,.msg-history-card,.msg-delivery-card,.msg-shop-order-card,.msg-music-card) :not(img):not(video){
