  width: var(--img-w) !important;
  height: auto !important;
  aspect-ratio: var(--img-ratio) !important;
  box-shadow: none !important;
  border-radius: var(--st-r) !important;
  margin: 0 calc(var(--st-gap2) + 2px) 0 0 !important;
}
.msg-image-wrapper > *,
.msg-image-card > * {
  min-width: 0 !important;
  min-height: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
}
